// Tier-2 SSR / declarative shadow DOM hydration (TESSER SSR-1/SSR-2).
// Page: demo/holo_element/ssr/index.html, generated by
// demo/hologram_app/priv/gen_ssr_page.exs via Noizu.Tessera.Hologram.Render.
// Served by demo/holo_element/serve.mjs on :5589 (nightly tier-2 hosts).
import {tesseraAsserts as asserts} from "../support/tessera/asserts";

const STATIC = "http://localhost:5589";

const shadow = () => cy.get('[data-cy="ssr-counter"]', {timeout: 15000}).shadow();

describe("tier 2 — SSR declarative shadow DOM hydration", () => {
  beforeEach(() => {
    cy.visit(`${STATIC}/ssr/`);
    // The server markup exists BEFORE the runtime runs, so wait for the
    // element's own mount handle, not for DOM.
    cy.get('[data-cy="ssr-counter"]', {timeout: 15000}).should(($el) => {
      expect(($el[0] as any).__mount, "runtime mounted").to.exist;
    });
  });

  it("the server markup is there before hydration, with server props", () => {
    cy.window().its("__ssrServerNodes.host").should("not.be.null");
    shadow().find('[data-cy="holo-counter-label"]').should("have.text", "server pings");
    shadow().find('[data-cy="holo-counter-count"]').should("have.text", "0");
  });

  it("hydrates in place: one subtree, same DOM nodes, actions work", () => {
    // no duplicated subtree (the stock-mount failure mode)
    shadow().find('[data-cy="holo-counter-root"]').should("have.length", 1);

    shadow()
      .find('[data-cy="holo-counter-inc"]')
      .click();

    cy.get('[data-cy="ssr-count-value"]').should("have.text", "2");
    shadow().find('[data-cy="holo-counter-count"]').should("have.text", "2");

    // node identity: the elements the SERVER created are the live ones
    cy.window().then((win) => {
      const root = win.document.getElementById("ssr-counter")!.shadowRoot!;
      const server = (win as any).__ssrServerNodes;
      expect(root.querySelector('[data-cy="holo-counter-count"]'), "count span identity").to.equal(server.count);
      expect(root.querySelector('[data-cy="holo-counter-inc"]'), "button identity").to.equal(server.inc);
    });

    // class re-applied by the attributes module after sel normalisation
    shadow().find('[data-cy="holo-counter-root"]').should("have.class", "tsr-counter");
    asserts.noConsoleErrors();
  });
});
